#pragma once
// aleks2 (DM2-d): the glibc ABI a Linux-built module bakes into its code, translated to the C library the
// game runs (newlib/libnx on Switch). One table (glibc_abi_table.inc, generated by research/dm2d/abi_probe.py
// from values measured with aarch64-linux-gnu and devkitA64): errno values, clock ids, open/fcntl flags and
// commands. The native side of every pair comes from the headers this file is compiled with, so on a glibc
// host (the qemu tests) every translation is the identity and the test checks the table's glibc column
// against glibc itself.
//
// errno: a module reads errno through __errno_location(), which glibc declares const, so the compiler keeps
// the pointer across calls (`errno = 0; f(); if (errno)`). The pointer must therefore be the C library's own
// errno; there is no translating it on the way out. Instead every function a Linux module calls through
// these shims leaves a glibc value in errno when it fails, and strerror/strerror_r/perror read a glibc value.
// errno values 1..34 are the same in both libraries; the shims cover the functions the catalog imports that
// can fail with one above that (research/dm2d/catalog-libc-imports.txt).
//
// struct tm: the first nine ints are laid out alike; glibc adds tm_gmtoff and tm_zone (56 bytes against 36).
// The functions that write one into the module's buffer fill both; those that only read one need nothing.
#include "elf_runtime_policy.hpp"

#include <vector>

namespace dusk::mods::elf::glibc {

// Value translation. Unknown values pass through unchanged.
int errno_to_glibc(int native);
int errno_from_glibc(int glibc);
int clock_from_glibc(int glibc);           // -1 for a glibc clock this library has no equivalent of
int oflags_from_glibc(int glibc);           // open() and F_SETFL flags
int oflags_to_glibc(int native);            // F_GETFL result
int fcntl_cmd_from_glibc(int glibc);        // -1 for a command this library does not know

// The shims, Linux-built modules only (Shim::linuxOnly), named as glibc names them.
std::vector<Shim> shims();

// For tests: the table as compiled -- {name, glibc value, native value (-999999 if not defined here)}.
struct Entry {
    const char* group;
    const char* name;
    long long glibc;
    long long native;
};
std::vector<Entry> table();

}  // namespace dusk::mods::elf::glibc
